extension ScrollMonster {
    /// The boss in `state`; `variant` (0...2) changes its colours week to week.
    public static func pixels(_ state: ScrollMonster.State, variant: Int) -> BuddyPixels {
        switch (state, ((variant % 3) + 3) % 3) {
        case (.healthy, 0): BuddySpriteData.monsterHealthy0
        case (.healthy, 1): BuddySpriteData.monsterHealthy1
        case (.healthy, _): BuddySpriteData.monsterHealthy2
        case (.hurt, 0): BuddySpriteData.monsterHurt0
        case (.hurt, 1): BuddySpriteData.monsterHurt1
        case (.hurt, _): BuddySpriteData.monsterHurt2
        case (.defeated, 0): BuddySpriteData.monsterDefeated0
        case (.defeated, 1): BuddySpriteData.monsterDefeated1
        case (.defeated, _): BuddySpriteData.monsterDefeated2
        }
    }
}

extension CalPose {
    /// The calendar character in this mood.
    public var pixels: BuddyPixels {
        switch self {
        case .idle: BuddySpriteData.calIdle
        case .happy: BuddySpriteData.calHappy
        case .sleepy: BuddySpriteData.calSleepy
        case .alarm: BuddySpriteData.calAlarm
        }
    }
}

